fn json_response(value:impl Serialize,status:u16,headers:&[(&str,&str)])->Response {
    if headers.iter().any(|(n,_)|matches!(n.to_ascii_lowercase().as_str(),"content-length"|"content-type"|"connection"|"transfer-encoding"|"x-content-type-options")) { return error("invalid_response_headers",500,"server-owned response header") }
    let mut response=(StatusCode::from_u16(status).unwrap(),serde_json::to_vec(&value).unwrap()).into_response();
    response.headers_mut().insert(header::CONTENT_TYPE,header::HeaderValue::from_static("application/json"));
    for(n,v) in headers { response.headers_mut().insert(header::HeaderName::from_bytes(n.as_bytes()).unwrap(),header::HeaderValue::from_str(v).unwrap()); }
    response
}
fn error(code:&str,status:u16,detail:&str)->Response { let mut r=(StatusCode::from_u16(status).unwrap(),serde_json::to_vec(&json!({"error":code,"detail":detail})).unwrap()).into_response(); r.headers_mut().insert(header::CONTENT_TYPE,header::HeaderValue::from_static("application/json")); r }
fn zero(v:&RequestInput,state:&str)->serde_json::Value { json!({"accession_key":v.accession_key,"artifact_total":0,"packing_units":0,"capacity_units":0,"overflow_units":0,"inspection_rounds":0,"priority_score":0,"accession_state":state}) }

fn decide(v:RequestInput,headers:&HeaderMap)->Response {
    if headers.get("authorization").and_then(|x|x.to_str().ok()).unwrap_or("") != "Bearer accession-045" { return json_response(zero(&v,"authorization_required"),401,&[("www-authenticate","Bearer realm=artifact-accession")]) }
    if [v.stable_units,v.fragile_units,v.packing_stations].iter().any(|x|*x<0) { return json_response(zero(&v,"invalid"),422,&[("x-validation","nonnegative")]) }
